ALTER TABLE drone.user_account ADD CONSTRAINT status_values CHECK (status IN ('ACTIVE','DISABLED'));
ALTER TABLE drone.config_version ADD CONSTRAINT status_values CHECK (status IN ('DRAFT','VALIDATED','APPROVED','RETIRED'));
ALTER TABLE drone.reobservation_request ADD CONSTRAINT requester_kind_values CHECK (requester_kind IN ('USER','SYSTEM'));
ALTER TABLE drone.media_asset ADD CONSTRAINT state_values CHECK (state IN ('WRITING','STORED','FAILED'));
ALTER TABLE drone.video_frame ADD CONSTRAINT analysis_mode_values CHECK (analysis_mode IN ('LIVE_DETECT','LIVE_TRACK_ONLY','HISTORICAL'));
ALTER TABLE drone.detection_observation ADD CONSTRAINT analysis_mode_values CHECK (analysis_mode IN ('LIVE_DETECT','LIVE_TRACK_ONLY','HISTORICAL'));
ALTER TABLE drone.person_candidate ADD CONSTRAINT geo_status_values CHECK (geo_status IN ('VALID','PENDING','INVALID'));
ALTER TABLE drone.flight_command ADD CONSTRAINT action_values CHECK (action IN ('GOTO','HOLD','RETURN','LAND','PAUSE','MISSION_UPLOAD'));
ALTER TABLE drone.flight_command ADD CONSTRAINT state_values CHECK (state IN ('REQUESTED','ACCEPTED','REJECTED','EXECUTING','COMPLETED','FAILED','UNCONFIRMED'));
ALTER TABLE drone.mission_event ADD CONSTRAINT publish_state_values CHECK (publish_state IN ('PENDING','PUBLISHED'));
ALTER TABLE drone.user_session ADD CONSTRAINT expiry_order CHECK (expires_at > issued_at);
ALTER TABLE drone.flight_command ADD CONSTRAINT expiry_order CHECK (expires_at > issued_at);
ALTER TABLE drone.user_session ADD CONSTRAINT revocation_order CHECK (revoked_at IS NULL OR revoked_at >= issued_at);
ALTER TABLE drone.user_account ADD CONSTRAINT normalized_login CHECK (login_id <> '' AND login_id = lower(btrim(login_id)));
ALTER TABLE drone.drone ADD CONSTRAINT control_times CHECK ((control_acquired_at IS NULL) = (control_expires_at IS NULL) AND (control_session_id IS NULL) = (control_acquired_at IS NULL) AND control_expires_at > control_acquired_at);
ALTER TABLE drone.mission ADD CONSTRAINT approval_pair CHECK ((approved_by IS NULL) = (approved_at IS NULL));
ALTER TABLE drone.config_version ADD CONSTRAINT approval_pair CHECK ((approved_by IS NULL) = (approved_at IS NULL));
ALTER TABLE drone.config_version ADD CONSTRAINT approved_evidence CHECK (status <> 'APPROVED' OR (approved_by IS NOT NULL AND validation_report IS NOT NULL));
ALTER TABLE drone.mission ADD CONSTRAINT granted_evidence CHECK (grant_status <> 'GRANTED' OR (approved_by IS NOT NULL AND active_revision IS NOT NULL AND readiness <> '{}'::jsonb));
ALTER TABLE drone.mission ADD CONSTRAINT end_order CHECK (ended_at IS NULL OR (started_at IS NOT NULL AND ended_at >= started_at));
ALTER TABLE drone.mission_revision ADD CONSTRAINT approved_revision CHECK (approved_at IS NULL OR (area_geom IS NOT NULL AND spatial_config_id IS NOT NULL AND coordinate_config_id IS NOT NULL AND policy_config_id IS NOT NULL AND grid_version IS NOT NULL AND area_denominators IS NOT NULL));
ALTER TABLE drone.search_region ADD CONSTRAINT remaining_area CHECK (remaining_area_m2 <= total_area_m2);
ALTER TABLE drone.reobservation_request ADD CONSTRAINT user_request CHECK (requester_kind <> 'USER' OR requested_by IS NOT NULL);
ALTER TABLE drone.video_frame ADD CONSTRAINT verified_capture CHECK (NOT capture_time_verified OR (capture_at IS NOT NULL AND time_evidence <> '{}'::jsonb));
ALTER TABLE drone.media_asset ADD CONSTRAINT stored_evidence CHECK (state <> 'STORED' OR (content_hash IS NOT NULL AND meta <> '{}'::jsonb));
ALTER TABLE drone.media_asset ADD CONSTRAINT asset_time_order CHECK (time_end IS NULL OR (time_start IS NOT NULL AND time_end >= time_start));
ALTER TABLE drone.media_asset ADD CONSTRAINT relative_storage CHECK (storage_uri <> '' AND storage_uri !~ '(^/|^[A-Za-z][A-Za-z0-9+.-]*:|(^|/)\.\.?(/|$)|\\)' );
ALTER TABLE drone.person_candidate ADD CONSTRAINT geo_evidence CHECK ((geo_status = 'VALID' AND latest_position IS NOT NULL AND coordinate_config_id IS NOT NULL AND ellipse IS NOT NULL) OR (geo_status IN ('PENDING','INVALID') AND latest_position IS NULL AND geo_reason IS NOT NULL));
ALTER TABLE drone.person_candidate ADD CONSTRAINT seen_order CHECK (last_seen IS NULL OR first_seen IS NULL OR last_seen >= first_seen);
ALTER TABLE drone.detection_observation ADD CONSTRAINT historical_mode CHECK (historical = (analysis_mode = 'HISTORICAL'));
ALTER TABLE drone.observation_cell ADD CONSTRAINT area_bound CHECK (cell_area_m2 > 0 AND valid_area_m2 <= cell_area_m2);
ALTER TABLE drone.flight_command ADD CONSTRAINT plan_context CHECK (plan_id IS NULL OR (mission_id IS NOT NULL AND mission_revision IS NOT NULL));
ALTER TABLE drone.alert ADD CONSTRAINT ack_pair CHECK ((ack_user_id IS NULL) = (acknowledged_at IS NULL));
ALTER TABLE drone.mission_event ADD CONSTRAINT publish_pair CHECK ((publish_state = 'PENDING' AND published_at IS NULL) OR (publish_state = 'PUBLISHED' AND published_at IS NOT NULL));
ALTER TABLE drone.mission_event ADD CONSTRAINT ref_pair CHECK ((ref_table IS NULL) = (ref_id IS NULL) AND (ref_table IS NULL OR ref_table IN ('user_account','user_session','drone','telemetry_sample','config_version','mission','mission_revision','search_plan','search_region','reobservation_request','video_frame','media_asset','person_candidate','detection_observation','observation_cell','flight_command','alert','mission_event')));
ALTER TABLE drone.config_version ADD CONSTRAINT no_self_parent_id CHECK (parent_id <> config_id);
ALTER TABLE drone.search_plan ADD CONSTRAINT no_self_parent_plan_id CHECK (parent_plan_id <> plan_id);
ALTER TABLE drone.search_plan ADD CONSTRAINT no_self_supersedes_plan_id CHECK (supersedes_plan_id <> plan_id);
ALTER TABLE drone.media_asset ADD CONSTRAINT no_self_source_asset_id CHECK (source_asset_id <> asset_id);
ALTER TABLE drone.detection_observation ADD CONSTRAINT no_self_supersedes_id CHECK (supersedes_id <> observation_id);
ALTER TABLE drone.mission_event ADD CONSTRAINT analysis_identity CHECK (NOT (event_type IN ('ANALYSIS_STARTED','ANALYSIS_ATTEMPT_STARTED','ANALYSIS_ATTEMPT_FAILED','ANALYSIS_COMPLETED','ANALYSIS_FAILED')) OR coalesce(payload->>'analysis_run_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND payload->>'frame_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND jsonb_typeof(payload->'analysis_revision')='number' AND payload->>'analysis_revision' ~ '^[1-9][0-9]*$' AND payload->>'job_hash' ~ '^[0-9a-f]{64}$',false));
ALTER TABLE drone.mission_event ADD CONSTRAINT attempt_identity CHECK (event_type NOT IN ('ANALYSIS_ATTEMPT_STARTED','ANALYSIS_ATTEMPT_FAILED') OR coalesce(jsonb_typeof(payload->'attempt_no')='number' AND payload->>'attempt_no' ~ '^[1-9][0-9]*$',false));
ALTER TABLE drone.mission_event ADD CONSTRAINT completed_identity CHECK (event_type <> 'ANALYSIS_COMPLETED' OR coalesce(payload->>'result_hash' ~ '^[0-9a-f]{64}$' AND jsonb_typeof(payload->'detection_count')='number' AND payload->>'detection_count' ~ '^(0|[1-9][0-9]*)$',false));
ALTER TABLE drone.mission_event ADD CONSTRAINT obs_group_identity CHECK (event_type <> 'OBS_GROUP_APPLIED' OR coalesce(mission_id IS NOT NULL AND payload->>'mission_id'=mission_id::text AND nullif(payload->>'grid_version','') IS NOT NULL AND nullif(payload->>'cell_id','') IS NOT NULL AND nullif(payload->>'obs_group','') IS NOT NULL AND jsonb_typeof(payload->'evidence_revision')='number' AND payload->>'evidence_revision' ~ '^[1-9][0-9]*$',false));
ALTER TABLE drone.detection_observation ADD CONSTRAINT analysis_identity CHECK (coalesce(association_evidence->>'analysis_run_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND jsonb_typeof(association_evidence->'analysis_revision')='number' AND association_evidence->>'analysis_revision' ~ '^[1-9][0-9]*$' AND association_evidence->>'job_hash' ~ '^[0-9a-f]{64}$',false));
CREATE UNIQUE INDEX asset_active_path ON drone.media_asset(storage_uri) WHERE state IN ('WRITING','STORED');
CREATE UNIQUE INDEX detection_run_index ON drone.detection_observation ((association_evidence->>'analysis_run_id'),detection_index);
CREATE UNIQUE INDEX analysis_started_run ON drone.mission_event ((payload->>'analysis_run_id')) WHERE event_type='ANALYSIS_STARTED';
CREATE UNIQUE INDEX analysis_started_revision ON drone.mission_event ((payload->>'frame_id'),(payload->>'analysis_revision')) WHERE event_type='ANALYSIS_STARTED';
CREATE UNIQUE INDEX analysis_terminal_run ON drone.mission_event ((payload->>'analysis_run_id')) WHERE event_type IN ('ANALYSIS_COMPLETED','ANALYSIS_FAILED');
CREATE UNIQUE INDEX obs_group_applied_once ON drone.mission_event(mission_id,(payload->>'grid_version'),(payload->>'cell_id'),(payload->>'obs_group'),(payload->>'evidence_revision')) WHERE event_type='OBS_GROUP_APPLIED';
CREATE UNIQUE INDEX analysis_attempt_started_once ON drone.mission_event ((payload->>'analysis_run_id'),(payload->>'attempt_no')) WHERE event_type='ANALYSIS_ATTEMPT_STARTED';
CREATE UNIQUE INDEX analysis_attempt_failed_once ON drone.mission_event ((payload->>'analysis_run_id'),(payload->>'attempt_no')) WHERE event_type='ANALYSIS_ATTEMPT_FAILED';
CREATE INDEX user_session_lookup_0 ON drone.user_session (user_id,expires_at) WHERE revoked_at IS NULL;
CREATE INDEX mission_lookup_0 ON drone.mission (drone_id,state);
CREATE INDEX telemetry_sample_lookup_0 ON drone.telemetry_sample (drone_id,sample_kind,source_time_utc DESC);
CREATE INDEX telemetry_sample_lookup_1 ON drone.telemetry_sample (mission_id,received_at);
CREATE INDEX config_version_lookup_0 ON drone.config_version (kind,status);
CREATE INDEX config_version_lookup_1 ON drone.config_version (asset_id);
CREATE INDEX search_plan_lookup_0 ON drone.search_plan (mission_id,status,generated_at DESC);
CREATE INDEX search_plan_lookup_1 ON drone.search_plan (region_id);
